#include "TernaryOp.h"
#include "ternary_metal.h" // Auto-generated by CMake

#ifdef _METAL_
#include "mlx/backend/metal/device.h"
#include "mlx/backend/metal/utils.h"
#endif

namespace mlx_ternary {

void TernaryMatMul::eval_cpu(
    const std::vector<mlx::core::array>& inputs,
    std::vector<mlx::core::array>& outputs) {
    throw std::runtime_error("TernaryMatMul::eval_cpu not yet implemented. Use GPU.");
}

void TernaryMatMul::eval_gpu(
    const std::vector<mlx::core::array>& inputs,
    std::vector<mlx::core::array>& outputs) {
    
#ifdef _METAL_
    auto& x = inputs[0];
    auto& w_packed = inputs[1];
    auto& scales = inputs[2];
    auto& out = outputs[0];

    // Allocate output
    out.set_data(mlx::core::allocator::malloc(out.nbytes()));

    auto& s = stream();
    auto& d = mlx::core::metal::device(s.device);

    // JIT compile the metal shader from the auto-generated string header
    auto lib = d.get_library("mlx_ternary", [&]() {
        return std::string(ternary_metal_source);
    });

    auto kernel = d.get_kernel("ternary_matmul_kernel", lib);

    auto& compute_encoder = mlx::core::metal::get_command_encoder(s);
    compute_encoder.set_compute_pipeline_state(kernel);

    // Dimensions
    uint M = 1;
    for (int i = 0; i < x.ndim() - 1; ++i) M *= x.shape(i);
    uint K = x.shape().back();
    uint N = w_packed.shape().back();

    compute_encoder.set_input_array(x, 0);
    compute_encoder.set_input_array(w_packed, 1);
    compute_encoder.set_input_array(scales, 2);
    compute_encoder.set_output_array(out, 3);

    compute_encoder.set_bytes(M, 4);
    compute_encoder.set_bytes(K, 5);
    compute_encoder.set_bytes(N, 6);

    MTL::Size grid_dims = MTL::Size(N, M, 1);
    
    // Ensure threadgroups are well balanced
    NS::UInteger max_threads = kernel->maxTotalThreadsPerThreadgroup();
    NS::UInteger max_x = std::min<NS::UInteger>(N, max_threads);
    NS::UInteger max_y = std::min<NS::UInteger>(M, max_threads / max_x);
    MTL::Size group_dims = MTL::Size(max_x, max_y, 1);

    compute_encoder.dispatch_threads(grid_dims, group_dims);
#else
    throw std::runtime_error("TernaryMatMul::eval_gpu: compiled without Metal support.");
#endif
}

mlx::core::array ternary_matmul(
    const mlx::core::array& x,
    const mlx::core::array& w_packed,
    const mlx::core::array& scales
) {
    auto s = mlx::core::default_stream(mlx::core::default_device());
    // Input validation
    if (x.ndim() < 2 || w_packed.ndim() < 2) {
        throw std::invalid_argument("[mlx_ternary] Inputs must be at least 2D.");
    }

    // IMPORTANT: Metal kernels expect linearly contiguous memory. 
    // Python reshape/slice ops often produce non-contiguous arrays with strides.
    auto x_c = mlx::core::contiguous(x, false, s);
    auto w_c = mlx::core::contiguous(w_packed, false, s);
    auto scales_c = mlx::core::contiguous(scales, false, s);
    
    // Output shape calculation: standard matmul rules
    auto out_shape = x.shape();
    out_shape.back() = w_packed.shape().back(); // x: (..., M, K), w: (K/4, N) -> out: (..., M, N)

    auto stream = mlx::core::to_stream(s);

    // Instantiate our custom op
    auto op = std::make_shared<TernaryMatMul>(stream);
    
    // Insert into MLX graph
    return mlx::core::array(
        out_shape, 
        x.dtype(),
        op,
        {x_c, w_c, scales_c}
    );
}

} // namespace mlx_ternary
